"""时区换算工具（仅标准库 zoneinfo，无外部服务）。

约定：
- 时钟（Clock.now()）返回 naive datetime，全库统一按 **UTC** 解释。
- 日程的 due_at 对外/存储均为带偏移 aware datetime（偏移来自其 IANA 时区）。
- 周期推进按“当地墙上时间”加整天/整周后重新本地化，DST 切换当天当地时刻不变。
"""
from __future__ import annotations

from datetime import datetime, timedelta, timezone
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

ISO = "%Y-%m-%dT%H:%M:%S%z"


def get_zone(name: str) -> ZoneInfo:
    try:
        return ZoneInfo(name)
    except ZoneInfoNotFoundError:
        raise ValueError(f"unknown IANA timezone: {name!r}")


def clock_now_to_utc(now: datetime) -> datetime:
    """时钟给出的 naive 时刻按 UTC 解释；aware 时刻归一到 UTC。"""
    if now.tzinfo is None:
        return now.replace(tzinfo=timezone.utc)
    return now.astimezone(timezone.utc)


def localize(wall: datetime, tzname: str) -> datetime:
    """把 naive 当地墙上时刻附加 IANA 时区，得到 aware datetime。"""
    if wall.tzinfo is not None:
        wall = wall.replace(tzinfo=None)
    return wall.replace(tzinfo=get_zone(tzname))


def to_utc(dt: datetime, tzname: str | None = None) -> datetime:
    if dt.tzinfo is None:
        dt = localize(dt, tzname or "UTC")
    return dt.astimezone(timezone.utc)


def format_aware(dt: datetime) -> str:
    """aware datetime -> ISO 串（带偏移，含冒号），可无损解析。"""
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    s = dt.strftime(ISO)  # e.g. 2026-03-08T09:00:00-0500
    return s[:-2] + ":" + s[-2:]


def parse_aware(s: str) -> datetime:
    """解析带偏移 ISO 串；兼容旧的 naive 'YYYY-MM-DD HH:MM:SS'（按 UTC）。"""
    t = s.strip().replace(" ", "T")
    # 补齐秒
    head, _, tail = t.partition("T")
    if len(tail.split("+")[0].split("-")[0]) == 5:  # HH:MM
        t += ":00"
    try:
        dt = datetime.fromisoformat(t)
    except ValueError:
        dt = datetime.strptime(t, ISO)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt


def parse_local(s: str) -> datetime:
    """解析 naive 当地墙上时刻串（YYYY-MM-DD HH:MM[:SS] 或 ISO）。"""
    t = s.strip().replace("T", " ")
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M"):
        try:
            return datetime.strptime(t, fmt)
        except ValueError:
            continue
    raise ValueError(f"unparsed local datetime: {s!r}")


def advance_wall(dt: datetime, step: timedelta, tzname: str) -> datetime:
    """在 tzname 的墙上时间上加 step（天/周），再重新本地化。

    DST 切换当天：保持当地墙上时刻（如每天 09:00），真实 UTC 时刻自动随
    偏移变化；春令时不存在的小时/秋令时重复的小时都不会产生两次或缺格。
    """
    wall = dt.astimezone(get_zone(tzname)).replace(tzinfo=None)
    return localize(wall + step, tzname)
